import{z as i,x as A,o as t,c as u,q as B,j as r,D as E,d as l,s as n,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"自动赎回 autocallable","description":"","frontmatter":{"title":"自动赎回 autocallable","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/autocallable.md","filePath":"quant/autocallable.md","lastUpdated":1791063341000}'),p={name:"quant/autocallable.md"};function d(c,a,m,h,D,b){const o=A("Mermaid");return t(),u("div",null,[a[2]||(a[2]=B('<h1 id="自动赎回-autocallable" tabindex="-1">自动赎回 autocallable <a class="header-anchor" href="#自动赎回-autocallable" aria-label="Permalink to &quot;自动赎回 autocallable&quot;">​</a></h1><div class="epigraph"><p>自动赎回是离散观察上的敲出：碰到上沿就终止并支付票息，否则继续；下跌侧再叠加敲入，就变成雪球一类的零售结构。</p><footer>—— 障碍与离散观察见 Broadie, Glasserman and Kou；结构分解见结构票据实务，对照境内雪球收益凭证</footer></div><p><a href="/quant/cliquet-forward-start">上一课</a>的重置仍让合约活到最后一段。Autocallable 的缺口是<strong>提前终止</strong>：观察日若 \\(S_{t_i}\\ge B_{\\mathrm{out}}\\)，合约结束，支付本金加票息。境内雪球在此之上再加敲入看跌，前沿课 <a href="/quant/snowball-pricing">雪球结构与定价</a> 已经写过完整三条终局。本课只补课程序列上的位置：把 autocall 当一般机制，与雪球条款对齐，不把雪球公式再推一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>没有敲入的纯 autocall（「凤凰」一类）近似：持有债券，卖出一串离散上障碍的敲出权，用票息当期权费。有敲入则再卖一份向下敲入看跌。问题是观察网格、票息是否记忆（memory / catch-up）、以及是否允许「已敲入仍可敲出」。这些条款改变的是路径集合，不是把票息贴现成债券收益率。</p><p><span class="marginnote">术语翻译：「敲出」是碰到上方门槛——合约提前结束、付当期票息走人；「敲入」是碰到下方门槛——激活一份看跌，亏损敞口从这一刻起挂在头上。一句话：上沿管「什么时候提前下车」，下沿管「跌深了要不要赔」；票息是你同时卖出这两类权利收到的保费。</span></p><p>把 autocallable 当 cliquet，漏掉终止：后面观察日的票息在已敲出路径上不存在，Vega 期限结构在近端观察日堆得更尖。把 autocallable 当连续障碍，漏掉离散漏检，监控课已经警告过。</p><h3 id="票息是或有的-不是-coupon-strip" tabindex="-1">票息是或有的，不是 coupon strip <a class="header-anchor" href="#票息是或有的-不是-coupon-strip" aria-label="Permalink to &quot;票息是或有的，不是 coupon strip&quot;">​</a></h3><p>记忆条款：若本次未敲出但上次也未付息，可能把未付票息累加到下一次敲出。这使支付依赖整段观察历史，状态要包括「已累计未付票息」与「是否已敲入」。PDE 维度立刻上去，实务以 <a href="/quant/mc-pricing">蒙特卡洛</a> 为主。不要用连续 Reiner–Rubinstein 八公式去估每月观察的 autocall。</p><p><span class="marginnote">发行人在敲出日终止，切断的是投资者剩余的上侧与时间价值。票息高往往对应敲入近、挂钩高波指数、或观察稀疏。用历史敲出频率去外推票息兑现率，忽略了卖出时隐波已经把未敲出路径标贵。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在合约列出的观察日 \\(\\{t_i\\}\\) 上检查敲出；敲入按日收盘或连续，以条款为准。风险中性期望对：敲出停时的票息与本金、到期未敲出未敲入的票息、到期已敲入的下跌参与，分别贴现。模型用与香草一致的局部波动或混合，并对照随机波动——autocall 对远期偏斜与缺口（跳空越过障碍）敏感。离散观察的连续性修正可当快速报价，生产仍应在真实网格上模拟。</p><p><span class="marginnote">数字实例：年化票息 12%、每季观察，则每次敲出拿 3% 加本金。若第二个观察日就敲出，你只持有半年、拿一期 3%，合约剩余的票息与时间价值全部与你无关；反过来若一路不敲出又敲入，那 12% 只是「说明书数字」，实际损益由敲入看跌决定。票息率高低与拿到的期望收益不是一回事。</span></p><p>对冲：观察日前的数字/障碍 Gamma、敲入后的 Delta 跳变、以及票息的利率与融资。发行人侧的希腊值见 <a href="/quant/snowball-dealer-hedging">雪球发行人的对冲</a>，本课不重写交易台流程。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每条路径在观察网格上被吸收或继续。活着的路径集合随时间缩小（已敲出的不再贡献），又可能在敲入后改变支付类型。价值对 \\(B_{\\mathrm{out}}\\) 附近的密度几乎是一触即付，对 \\(B_{\\mathrm{in}}\\) 附近是敲入看跌。因此 autocallable 的隐波风险是<strong>障碍点上的数字风险 + 剩余期限的香草风险</strong>，不能收成一个 ATM Vega。</p>',16)),(t(),r(s,null,{default:E(()=>[n(o,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20Obs%5B%22%E8%A7%82%E5%AF%9F%E6%97%A5%E7%BD%91%E6%A0%BC%22%5D%20--%3E%20Out%5B%22%E8%A7%A6%E5%8F%8A%E6%95%B2%E5%87%BA%20%E7%BB%88%E6%AD%A2%E4%BB%98%E6%81%AF%22%5D%0A%20%20Obs%20--%3E%20Cont%5B%22%E6%9C%AA%E6%95%B2%E5%87%BA%E5%88%99%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20Cont%20--%3E%20In%5B%22%E6%98%AF%E5%90%A6%E5%B7%B2%E6%95%B2%E5%85%A5%22%5D%0A%20%20In%20--%3E%20Down%5B%22%E5%88%B0%E6%9C%9F%E4%B8%8B%E8%B7%8C%E5%8F%82%E4%B8%8E%22%5D%0A%20%20In%20--%3E%20Bond%5B%22%E5%88%B0%E6%9C%9F%E8%BF%98%E6%9C%AC%E4%BB%98%E6%81%AF%22%5D%0A%20%20Out%20--%3E%20Stop%5B%22%E5%90%8E%E7%BB%AD%E7%A5%A8%E6%81%AF%E6%B6%88%E5%A4%B1%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"边界",tabindex:"-1"},[l("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[4]||(a[4]=e("p",null,"跳空、停牌、涨跌停使「收盘是否触及」与连续路径不一致，合同必须定义用哪一个价。多标的最差表现（worst-of）autocall 把相关变成一等风险，篮子课的符号在这里是：相关下降，worst-of 更易敲入、更难一起敲出，结构更便宜（对卖方更贵）。不要用单资产闭式去估 worst-of。",-1)),(t(),r(s,null,{default:E(()=>[n(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22worst-of%3A%20%E6%94%AF%E4%BB%98%E6%8C%89%E7%AF%AE%E5%AD%90%E9%87%8C%E6%9C%80%E5%B7%AE%E7%9A%84%E9%82%A3%E4%B8%AA%E7%AE%97%22%5D%20--%3E%20C%7B%22%E6%A0%87%E7%9A%84%E9%97%B4%E7%9B%B8%E5%85%B3%E4%B8%8B%E9%99%8D%22%7D%0A%20%20C%20--%3E%7C%E6%9B%B4%E5%88%86%E6%95%A3%7C%20IN%5B%22%E6%9C%80%E5%B7%AE%E8%80%85%E6%9B%B4%E5%AE%B9%E6%98%93%E8%B7%8C%E6%B7%B1%3A%20%E6%95%B2%E5%85%A5%E6%A6%82%E7%8E%87%E4%B8%8A%E5%8D%87%22%5D%0A%20%20C%20--%3E%7C%E8%B5%B0%E5%8A%BF%E9%94%99%E5%BC%80%7C%20OUT%5B%22%E5%85%A8%E4%BD%93%E4%B8%80%E8%B5%B7%E6%95%B2%E5%87%BA%E6%9B%B4%E9%9A%BE%3A%20%E6%8F%90%E5%89%8D%E7%BB%88%E6%AD%A2%E5%8F%98%E5%B0%91%22%5D%0A%20%20IN%20--%3E%20P%5B%22%E7%BB%93%E6%9E%84%E5%AF%B9%E5%8D%96%E6%96%B9%E6%9B%B4%E8%B4%B5%3A%20%E5%90%8C%E7%A5%A8%E6%81%AF%E4%B8%8B%E4%BB%B7%E5%80%BC%E9%99%8D%E4%BD%8E%22%5D%0A%20%20OUT%20--%3E%20P%0A%20%20P%20--%3E%20H%5B%22%E5%AF%B9%E5%86%B2%E9%87%8D%E7%82%B9%E4%BB%8E%E5%8D%95%E8%B5%84%E4%BA%A7%E6%B3%A2%E5%8A%A8%E8%BD%AC%E5%90%91%E7%9B%B8%E5%85%B3%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">直觉类比：worst-of 像木桶短板——篮子涨没涨不看平均，只看最矮的那块板。五只股票里四只创新高、一只跌 30%，你的结构就按那只跌的算；而它们越「各走各的」，总有一只掉队的可能性越大。这就是相关下降让 worst-of 同时更易敲入、更难敲出的原因。</span></p><p>适当性、不得宣传保本、柜台衍生品规范是约束。本课不讨论如何改写条款以绕过适当性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Autocallable 是离散敲出加可选敲入；票息是或有期权费，不是债券 coupon。</li><li>状态含观察历史、已敲入与记忆票息；生产估值用合约网格上的模拟。</li><li>雪球是该类在境内的常见包装，细节不在本课重复推导。</li><li>出处：离散障碍修正见 Broadie, Glasserman and Kou, <em>Mathematical Finance</em>, 1997；结构分解见雪球与结构票据实务。</li></ul>',4))])}const C=i(p,[["render",d]]);export{_ as __pageData,C as default};
